head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > M > validate]<br/>컴포넌트의 입력값에 대한 유효성 체크를 실행한 후 결과값을 반환합니다.",
    "validation" : [
        "컴포넌트의 입력값에 대한 유효성 체크를 실행한 후 결과값을 반환합니다.",
        "mandatory, maxlength, minlength, maxByteLength, minByteLength 속성이 한 개 이상 설정되어야 실행됩니다.",
        "유효성 검증에 성공한 경우 true 를 반환합니다.",
        "유효성 검증에 실패한 경우 false 를 반환합니다.",
        "mandatory, maxlength, minlength, maxByteLength, minByteLength 속성 순서로 유효성 체크가 실행됩니다.",
        "유효성 체크를 통과하지 못한 속성에서 체크가 중단됩니다.",
        "displaymessage=true 인 경우 유효성 체크를 통과하지 못한 속성에 대한 실패 메시지가 출력되며, invalidMessage 속성으로 실패 메시지를 변경할 수 있습니다.",
        "displaymessage=true 인 경우 유효성 체크를 통과하지 못한 속성에 대한 실패 메시지가 출력되며, invalidMessageFunc 속성으로 실패 메시지를 변경할 수 있습니다.",
        "실패 메시지가 출력된 후 false 를 반환합니다.",
        "유효성 체크를 통과하지 못한 컴포넌트가 포커스 됩니다.",
        "validator 속성에 설정된 사용자 정의 함수와 별개로 유효성 체크를 실행합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.check_validate = function (target) {
    let rtn = target.validate();

    wf_body_bottom.getObj("scwin").setReturnValue("return : " + rtn);
}



// target1 (모든 속성 설정 → 유효한 값 입력 → 유효성 검증 성공 후 true 반환)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("abcd");
};

scwin.btn_validate1_onclick = function (e) {
    scwin.btn_setValue1_onclick();
    scwin.check_validate(target1);
}



// target2 (mandatory 실패 → false 반환, 실패 컴포넌트 포커스)
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("");
};

scwin.btn_validate2_onclick = function (e) {
    scwin.btn_setValue2_onclick();
    scwin.check_validate(target2);
}



// target3 (mandatory 성공 → maxlength 실패 후 false 반환)
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("abcdefg");
};

scwin.btn_validate3_onclick = function (e) {
    scwin.btn_setValue3_onclick();
    scwin.check_validate(target3);
}



// target4 (mandatory, maxlength 성공 → minlength 실패 후 false 반환)
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("a");
};

scwin.btn_validate4_onclick = function (e) {
    scwin.btn_setValue4_onclick();
    scwin.check_validate(target4);
}



// target5 (mandatory, maxlength, minlength 성공 → maxByteLength 실패 후 false 반환)
// maxlength=10, minlength=2, maxByteLength=4, minByteLength=3 → 'abcde'(5자) → maxlength PASS, minlength PASS, maxByteLength FAIL
scwin.btn_setValue5_onclick = function (e) {
    target5.setValue("abcde");
};

scwin.btn_validate5_onclick = function (e) {
    scwin.btn_setValue5_onclick();
    scwin.check_validate(target5);
}



// target6 (mandatory, maxlength, minlength, maxByteLength 성공 → minByteLength 실패 후 false 반환)
// maxlength=10, minlength=1, maxByteLength=6, minByteLength=3 → 'a'(1자=1byte) → minlength PASS, maxByteLength PASS, minByteLength FAIL
scwin.btn_setValue6_onclick = function (e) {
    target6.setValue("a");
};

scwin.btn_validate6_onclick = function (e) {
    scwin.btn_setValue6_onclick();
    scwin.check_validate(target6);
}



// target7 (유효성 속성 미설정 → validate() 호출해도 체크가 실행되지 않음, true 반환)
scwin.btn_setValue7_onclick = function (e) {
    target7.setValue("");
};

scwin.btn_validate7_onclick = function (e) {
    scwin.btn_setValue7_onclick();
    scwin.check_validate(target7);
}



// target8 (mandatory=true, displaymessage=true, invalidMessage 설정 → 실패 메시지가 사용자 메시지로 변경, false 반환)
scwin.btn_setValue8_onclick = function (e) {
    target8.setValue("");
};

scwin.btn_validate8_onclick = function (e) {
    scwin.btn_setValue8_onclick();
    scwin.check_validate(target8);
}



// target9 (mandatory=true, displaymessage=true, invalidMessageFunc 설정 → 실패 메시지가 사용자 정의 함수 결과로 변경, false 반환)
scwin.btn_setValue9_onclick = function (e) {
    target9.setValue("");
};

scwin.btn_validate9_onclick = function (e) {
    scwin.btn_setValue9_onclick();
    scwin.check_validate(target9);
}



// target10 (mandatory=true, displaymessage=false → 실패 메시지 출력 없이 false 반환)
scwin.btn_setValue10_onclick = function (e) {
    target10.setValue("");
};

scwin.btn_validate10_onclick = function (e) {
    scwin.btn_setValue10_onclick();
    scwin.check_validate(target10);
}



// target11 (validator 사용자 정의 함수 설정 + mandatory=true → validate() 는 validator 와 별개로 mandatory 만 체크하여 PASS)
scwin.btn_setValue11_onclick = function (e) {
    target11.setValue("abc");
};

scwin.btn_validate11_onclick = function (e) {
    scwin.btn_setValue11_onclick();
    scwin.check_validate(target11);
}



// invalidMessageFunc 사용자 정의 함수
scwin.fn_msg = function () {
    let invalidType = this.getType();
    let msg = "사용자 정의 메시지: " + invalidType + " 유효성 실패";
    return msg;
}



// validator 사용자 정의 함수 (validate() 와 별개로 동작)
scwin.fn_validator = function () {
    return false;
}



scwin.target_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====" + e.target.id + "_onfocus=====");
};
